        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Falta determinar o término novo para calcular eventual alteração dos dias cobrados de apoio."
